#include "insignia_attention.cuh"
#include <cuda_runtime.h>
namespace insignia {
__global__ __launch_bounds__(256,2) void gqa_decode_kernel(const float*__restrict__ q,const float*__restrict__ kc,const float*__restrict__ vc,float*__restrict__ out,int tokens){const int head=blockIdx.x,tid=threadIdx.x,kvh=head>>2;const float scale=.0625f;extern __shared__ float sm[];float*score=sm;float mx=-3.402823466e+38F;for(int t=tid;t<tokens;t+=256){float z=0;for(int d=0;d<256;d++)z=fmaf(q[head*256+d],kc[(t*4+kvh)*256+d],z);z*=scale;score[t]=z;mx=fmaxf(mx,z);}for(int m=16;m;m>>=1)mx=fmaxf(mx,__shfl_xor_sync(0xffffffff,mx,m));__shared__ float red[8];int lane=tid&31,warp=tid>>5;if(lane==0)red[warp]=mx;__syncthreads();if(warp==0){mx=lane<8?red[lane]:-3.402823466e+38F;for(int m=16;m;m>>=1)mx=fmaxf(mx,__shfl_xor_sync(0xffffffff,mx,m));if(lane==0)red[0]=mx;}__syncthreads();mx=red[0];float den=0;for(int t=tid;t<tokens;t+=256){float e=__expf(score[t]-mx);score[t]=e;den+=e;}for(int m=16;m;m>>=1)den+=__shfl_xor_sync(0xffffffff,den,m);if(lane==0)red[warp]=den;__syncthreads();if(warp==0){den=lane<8?red[lane]:0;for(int m=16;m;m>>=1)den+=__shfl_xor_sync(0xffffffff,den,m);if(lane==0)red[0]=1.f/den;}__syncthreads();float z=0;for(int t=0;t<tokens;t++)z=fmaf(score[t]*red[0],vc[(t*4+kvh)*256+tid],z);out[head*256+tid]=z;}
void gqa_decode(const float*q,const float*k,const float*v,float*out,int tokens,cudaStream_t s){if(tokens<=0)return;gqa_decode_kernel<<<16,256,size_t(tokens)*sizeof(float),s>>>(q,k,v,out,tokens);}
}
